def assemble_logs():
 for p in (ROOT/'results').glob('*/*/metrics.json'):
  out=p.parent;m=json.loads(p.read_text());rid=out.name;model=m['model'];candidates=[]
  logs=list((ROOT/'logs').glob(rid.replace('_seed42','')+'*attempt*.log'))+list((ROOT/'logs').glob(model+'_'+rid+'*attempt*.log'))+list((ROOT/'logs').glob('DAG_fresh_'+rid+'*attempt*.log'))
  for log in sorted(logs):
   b=log.read_bytes()
   if model=='WorldTS' and b'WorldTS' not in b and b'worldts' not in b:continue
   if model=='DAG' and b'WorldTS' in b:continue
   candidates.append(log)
  if model=='DAG' and m['run_type']=='verified_reuse':
   old=pathlib.Path('D:/conditional_latent_loop_seed2021_v1/logs')/f'run_official_dag_{m["dataset"]}_{m["horizon"]}.log'
   dst=out/'original_training.log';shutil.copy2(old,dst);candidates=[dst]+candidates
  assert candidates,out.name
  destination=out/'train.log'
  with destination.open('wb') as f:
   for log in candidates:f.write(('\n=== Original retained log: '+str(log)+' ===\n').encode());f.write(log.read_bytes())
  write_json(out/'log_manifest.json',[{'path':str(log),'sha256':sha(log),'bytes':log.stat().st_size} for log in candidates])
