 write_json(ROOT/'reports/dag_v1_comparison.json',comparison);write_csv(ROOT/'results/dag_v1_comparison.csv',comparison)
 disk=sum(p.stat().st_size for p in ROOT.rglob('*') if p.is_file());counts=collections.Counter(r['status'] for r in rows);fresh=sum(r['run_type']=='fresh_run' for r in rows);totalfresh=sum(r['train_seconds'] for r in rows if r['run_type']=='fresh_run');reuse=sum(r['train_seconds'] for r in rows if r['run_type']=='verified_reuse');evals=sum(r['eval_seconds'] for r in rows)
 sources={k:COMMITS[k] for k in COMMITS};archive=[]
